def build_cast(world):
    rng = random.Random(20261101)
    result, briefs = {}, []
    for row in CAST:
        draw = rng.random()
        count = 1 if draw < .65 else 2 if draw < .9 else 3
        affinity = [row['primary']] + rng.sample(row['secondary'], count - 1)
        pose = rng.choice(row['poses'])
        location = row['location']
        assert location in world['locations'], location
        area = location + ' - ' + row['area'] if row['area'] else next(iter(world['locations'][location]['areas']))
        assert area in world['locations'][location]['areas'], area
        info = row['public'] + ' ' + row['visual'] + '\n\n**Equipment:** ' + row['equipment']
        profile = [('Gender', row['gender'].capitalize()), ('Age', row['age']), ('Species', row['species']), ('Role in faction', row['role'])]
        if row['name'] == 'Suzuha Midorise':
            profile.append(('Academic standing', 'Fourth year, Hydra Head Academy; field thesis in progress'))
        profile.append(('Magic affinity', ', '.join(affinity)))
        info += '\n\n' + '\n'.join('- **' + k + ':** ' + str(v) for k, v in profile)
        hidden = '\n\n'.join('**' + label + ':** ' + row[key] for label, key in [
            ('Private motive', 'motive'), ('What they conceal', 'secret'), ('Concealment and knowledge', 'knowledge'),
            ('Pressure point', 'pressure'), ('Relationships', 'relationships'), ('How it surfaces', 'surfaces')])
        npc = dict(name=row['name'], currentLocation=location, currentArea=area,
                   type='Ghost' if row['name'] == 'Ysolenne' else 'Student' if row['name'] == 'Suzuha Midorise'
                   else 'Artisan' if row['name'] == 'Tetsuya Kanamori' else 'Resident' if row['name'] in ['Nae Komorida','Masaru Hasebe'] else 'Adventurer',
                   properName=row['name'], detailType='detailed', tier=row['tier'], visualDescription=row['visual'],
                   basicInfo=info, gender=row['gender'], hiddenInfo=hidden,
                   personality=[label + ': ' + value for label, value in zip(
                       ['Core','Default behavior','Under Pressure','Speaking Style','Courtship Style','Jealousy Style','Routine or Quirk'], row['personality'])],
                   abilities=row['abilities'], level=row['level'], healthMultiplier=1, successBonus=0,
                   damageModifier=0, damageReductionModifier=0, faction=row['faction'], initialKnown=False,
                   initialRelationship=0, portraitUrl='')
        minor_workings = {
            'Wind': 'Thread Breeze: Guides a light ribbon or loose page on a small controlled current.',
            'Light': 'Candle Gleam: Creates a modest nearby light for inspection or finding a dropped object.',
            'Earth': 'Settled Stone: Steadies one loose stone or a small patch of gravel through deliberate contact.',
            'Fire': 'Hearth Spark: Lights prepared dry tinder with a small controlled spark.',
            'Nature': 'Green Stir: Encourages a small existing plant to turn toward light or uncurl a leaf.',
            'Sound': 'Clear Note: Carries a short chosen note a little more clearly across a noisy room.',
            'Illusion': 'Borrowed Color: Alters the apparent color of one small held object briefly, without changing its substance.',
            'Lightning': 'Snap Current: Gives a small prepared conductor a brief controlled charge, not a storm-scale attack.',
            'Enchantment': 'Firm Stitch: Temporarily reinforces a small existing seam during careful work.',
            'Divination': 'Patient Impression: Studies a present sample for a faint uncertain magical impression, which still needs corroboration.',
            'Metal': 'True Ring: Coaxes a clean note from a small metal fitting to help inspect it.',
            'Water': 'Cup Current: Moves a modest amount of existing water between nearby open vessels.',
            'Summoning': 'Paper Helper: Briefly calls a tiny non-sentient construct to carry a light note within the room.'}
        for school in affinity[1:]:
            npc['abilities'].insert(-1, minor_workings[school])
        assert row['name'] not in world['npcs'], row['name']
        result[row['name']] = npc
        briefs.append(dict(name=row['name'], major=row['major'], affinity=affinity, affinityDraw=draw,
                           affinityCount=count, pose=pose, eligiblePoses=row['poses'], location=location, area=area))
    return result, briefs
